awk -F'\t' '$1 ~ /^zorf/ {
  w=$1; p=$2;
  if (p == w "s") t="+s";
  else if (p == w "es") t="+es";
  else if (p == w) t="UNCHANGED";
  else if (substr(w,length(w))=="y" && p == substr(w,1,length(w)-1) "ies") t="y->ies";
  else t="OTHER:" p;
  end2 = (length(w)>=2)? substr(w,length(w)-1) : substr(w,length(w));
  print t "\t" end2;
}' data/core-rules.tsv | sort | uniq -c | sort -k2,2 | awk '{print $1"  "$2"  "$3}' | sort -k2,2 > /tmp/probe/scratch/zsum.txt
awk -F'\t' '$1 ~ /^zorf/ {
  w=$1; p=$2;
  if (p == w "s") t="+s";
  else if (p == w "es") t="+es";
  else if (p == w) t="UNCH";
  else if (substr(w,length(w))=="y" && p == substr(w,1,length(w)-1) "ies") t="y2ies";
  else t="OTHER(" p ")";
  print t;
}' data/core-rules.tsv | sort | uniq -c
echo "=== non +s cases (zorf stem) ==="
awk -F'\t' '$1 ~ /^zorf/ && $2 != $1 "s"' data/core-rules.tsv | sort | tr '\t' ' ' | column -c 200

cd /tmp/probe/lists/core
awk 'BEGIN{
 n=split("a b c d e f g h i j k l m n o p q r s t u v w x y z",L," ");
 for(i=1;i<=n;i++)for(j=1;j<=n;j++)for(k=1;k<=n;k++) print "zorf" L[i] L[j] L[k];
}' > s5.txt
wc -l s5.txt; head -3 s5.txt; tail -3 s5.txt

cd /tmp/probe
