echo "=== classify ==="
awk -F'\t' '{w=$1;p=$2;
 if(p==w"s")t="+s"; else if(p==w"es")t="+es"; else if(p==w)t="UNCH";
 else if(substr(w,length(w))=="y" && p==substr(w,1,length(w)-1)"ies")t="y2ies";
