 if(p==w"s"||p==w"es"||p==w)next;
 if(substr(w,length(w))=="y" && p==substr(w,1,length(w)-1)"ies")next;
 print}' scratch/s5.tsv
echo "=== distinct 3-char endings per class ==="
awk -F'\t' '{w=$1;p=$2;e=substr(w,length(w)-2);
 if(p==w"s")t="+s"; else if(p==w"es")t="+es"; else if(p==w)t="UNCH";
 else if(substr(w,length(w))=="y" && p==substr(w,1,length(w)-1)"ies")t="y2ies"; else t="OTHER";
 print t"\t"e}' scratch/s5.tsv | sort -u | awk -F'\t' '{c[$1]++} END{for(k in c)print c[k],k}'

cd /tmp/probe
cat > /tmp/probe/predcore.awk <<'EOF'
function pl(w,  n,c2,last){
  n=length(w); if(n==0) return w;
  last=substr(w,n,1);
  if(n>=2 && substr(w,n-1,2)=="es") return w;
  if(last=="y"){ if(n>=2){ c2=substr(w,n-1,1); if(index("aeiou",c2)==0) return substr(w,1,n-1) "ies"; } return w "s"; }
  if(last=="s") return w "es";
  if(n>=2 && (substr(w,n-1,2)=="ch"||substr(w,n-1,2)=="sh")) return w "es";
  return w "s";
}
BEGIN{FS="\t"}
{ e=pl($1); if(e!=$2) print "MISMATCH\t"$1"\t"$2"\tpred="e; else ok++ }
END{ print "OK="ok }
EOF
awk -f /tmp/probe/predcore.awk data/core-rules.tsv | tail -40
